window.__sweepInit=(function(){
  var G=Arena.Game, W=G.world, Ab=Arena.Combat.AbilitySystem, St=Arena.Combat.StatusSystem, Met=Arena.Sim.ArenaMetrics;

  function enemyOf(p){for(var i=0;i<W.entities.length;i++){var e=W.entities[i];if(e.team!==p.team&&e.alive)return e;}return null;}
  function allyOf(p){for(var i=0;i<W.entities.length;i++){var e=W.entities[i];if(e!==p&&e.team===p.team&&e.alive)return e;}return null;}

  /* Coloca al lanzador a distancia de tiro CON visión comprobada. Situarlo a
     ciegas detrás de una columna produce un 'los' que parece un defecto del
     juego y es un defecto del arnés. */
  function placeWithLoS(p,t,range){
    var want=Math.max(1.5,Math.min(range*0.65,range-1.5));
    for(var deg=0;deg<360;deg+=7){
      var a=deg*Math.PI/180;
      var x=t.pos.x+Math.cos(a)*want, z=t.pos.z+Math.sin(a)*want;
      if(!Met.walkable(W.arena,x,z,0.6))continue;
      p.pos.x=x; p.pos.z=z; p.pos.y=0; p.prevPos.x=x; p.prevPos.z=z;
      p.yaw=Math.atan2(t.pos.x-x,t.pos.z-z); p.prevYaw=p.yaw;
      if(W.hasLineOfSight(p.eyePos(),t.centerPos(),p,t))return true;
    }
    return false;
  }

  function clear(e){while(e.statuses.length)St.removeInstance(W,e,e.statuses[0],'sweep');}
  function names(e){return e.statuses.map(function(s){return s.defId;});}

  window.__sweepReport=function(classId){
    G.setPlayerClass(classId);
    W.settings.aiEnabled=false;
    var p=W.getPlayer(); if(!p)return {classId:classId,error:'sin jugador'};
    var foe=enemyOf(p), friend=allyOf(p);
    if(!foe)return {classId:classId,error:'sin enemigo'};
    foe.aiEnabled=false; if(friend)friend.aiEnabled=false;
    foe.hpMax=200000; foe.hp=200000;
    var rows=[];

    for(var i=0;i<p.abilities.length;i++){
      var id=p.abilities[i], ab=Arena.Data.abilities[id];
      var wantsAlly=(ab.target==='ally'||ab.target==='allyOrSelf');
      var subject=wantsAlly?(friend||p):foe;
      if(wantsAlly&&subject!==p){subject.hpMax=2000;subject.hp=900;}
      else if(wantsAlly){p.hp=Math.round(p.hpMax*0.5);}

      p.gcdUntil=0; p.cooldowns=Object.create(null); p.schoolLockouts=Object.create(null);
      p.resource=p.resourceMax; p.pendingCast=null;
      clear(p); clear(foe); if(friend)clear(friend);
      var ok=placeWithLoS(p,wantsAlly?subject:foe,ab.range||3);
      if(wantsAlly&&subject===p)ok=true;
      p.targetId=subject.id;

      var res0=p.resource, hp0=foe.hp, subHp0=subject.hp, heal0=p.stats.healingDone;
      var r=Ab.tryUse(W,p,id,{targetId:subject.id,target:subject,groundPoint:{x:foe.pos.x,y:0,z:foe.pos.z}});
      var casteo=!!p.pendingCast;
      /* Lo instantáneo gasta DENTRO de tryUse: si el primer muestreo se toma
         después, el coste queda invisible y parece que las instantáneas son
         gratis. El arnés mentía, no el juego. */
      var maxDrop=Math.max(0,res0-p.resource);
      var prev=p.resource, cdSeen=0;
      var ticks=Math.ceil(((ab.castTime||0)+1.6)*30);
      for(var s=0;s<ticks;s++){
        W.stepSeconds(1/30);
        var drop=prev-p.resource; if(drop>maxDrop)maxDrop=drop; prev=p.resource;
        if((p.cooldowns[id]||0)>0)cdSeen=1;
      }
      rows.push({
        slot:i+1, id:id, nombre:ab.name, objetivo:ab.target,
        colocado:ok, aceptada:!!(r&&r.ok!==false&&r!==false), motivo:(r&&r.reason)||null,
        castTime:ab.castTime||0, casteo:casteo,
        gasto:+maxDrop.toFixed(1), coste:ab.cost||0,
        cd:cdSeen, cdDecl:ab.cooldown||0,
        dmg:+(hp0-foe.hp).toFixed(1),
        curado:+(p.stats.healingDone-heal0).toFixed(1),
        subeVida:+(subject.hp-subHp0).toFixed(1),
        efFoe:names(foe), efAliado:friend?names(friend):[], efUno:names(p)
      });
    }
    return {classId:classId, clase:Arena.Data.classes[classId].name, tieneAliado:!!friend, filas:rows};
  };
  return 'listo';
})()
